def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (ignore it)
        if '+' in v:
            v = v.split('+')[0]

        # Split pre-release
        if '-' in v:
            base, prerelease = v.split('-', 1)
        else:
            base = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                # Check if all digits
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(item):
        version, original_index = item
        major, minor, patch, prerelease_identifiers = parse_version(version)

        # Version without pre-release sorts after version with pre-release
        # So if no pre-release, we use a tuple that sorts after any pre-release
        if not prerelease_identifiers:
            prerelease_sort_key = (1,)  # sorts after (0, ...)
        else:
            prerelease_sort_key = (0, prerelease_identifiers)

        return (major, minor, patch, prerelease_sort_key, original_index)

    # Add original index to maintain stability
    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for v, _ in sorted_versions]

